import os, sys, time
# Timed writer: each argument is hex bytes to write, or sNNN to sleep NNN ms.
for arg in sys.argv[1:]:
    if arg.startswith('s'):
        time.sleep(int(arg[1:]) / 1000)
    else:
        os.write(1, bytes.fromhex(arg))

